  ('On İkinci Gece''de Viola erkek kılığına girdiğinde kendini hangi adla tanıtır?', 'What name does Viola use when disguised as a man in Twelfth Night?', '["Cesario","Sebastian","Orsino","Malvolio"]'::jsonb),
  ('Don Kişot şövalye ilan edilmek istediği ilk konaklama yerini ne sanır?', 'What does Don Quixote imagine his first lodging place to be when he asks to be knighted?', '["Castle","Monastery","Palace garden","Barracks"]'::jsonb),
  ('Matilda''daki müdür Trunchbull''un geçmişte yarıştığı atletizm dalı hangisidir?', 'In which athletics event did headmistress Trunchbull compete in the past in Matilda?', '["Hammer throw","Discus throw","Shot put","Javelin throw"]'::jsonb),
  ('Doğu Ekspresinde Cinayet''te cinayetin işlendiği vagonun hattı hangi liman şehrine gider?', 'To which port city is the carriage where the murder takes place bound in Murder on the Orient Express?', '["Calais","Marseille","Le Havre","Cherbourg"]'::jsonb)
  ) v(soru, en_soru, en_secenekler)
  join public.questions q on q.soru = v.soru and q.created_at >= transaction_timestamp()
on conflict (question_id, dil) do nothing;

-- ---------------------------------------------------- Çevrilmeyenler
insert into public.ceviri_atlanan (question_id, dil, neden, kod)
select q.id, 'en', v.neden, 'cevrilemez'
  from (values
  ('Abidin Dino''nun birbirine uzanan, sıkılan veya açılan biçimlerle sıkça çizdiği beden bölümü hangisidir?', 'Türkiye yerel kültürü; stil kararı.'),
  ('Teoman''ın 1996 tarihli ilk albümündeki hangi şarkı adını bir çiçekten alır?', 'Türkiye yerel kültürü; stil kararı.'),
  ('Bülent Ortaçgil''in ilk albümü Benimle Oynar Mısın hangi yılda yayımlandı?', 'Türkiye yerel kültürü; stil kararı.'),
  ('Naim Süleymanoğlu''nun Türkiye''de yaygın kullanılan lakabı hangisidir?', 'Türkiye yerel kültürü; stil kararı.'),
  ('Cemal Süreya''nın doğum soyadı hangisidir?', 'Türkiye yerel kültürü; stil kararı.')
  ) v(soru, neden)
  join public.questions q on q.soru = v.soru and q.created_at >= transaction_timestamp()
on conflict (question_id, dil) do nothing;

-- ---------------------------------------------------- Karıştırma (TR + EN aynı permütasyon)
drop table if exists pg_temp._parti_karistir;
create temp table _parti_karistir as
select q.id, array_agg(s.idx order by s.rnd) as perm
  from public.questions q
  cross join lateral (
    select (ordinality - 1)::int as idx, random() as rnd
      from jsonb_array_elements(q.secenekler) with ordinality
  ) s
 where q.created_at >= transaction_timestamp()
 group by q.id;

update public.questions q
   set secenekler = (select jsonb_agg(q.secenekler -> u.p order by u.o)
                       from unnest(k.perm) with ordinality u(p, o)),
       dogru_cevap = (array_position(k.perm, q.dogru_cevap::int) - 1)::smallint
  from _parti_karistir k
 where q.id = k.id;

update public.question_translations t
   set secenekler = (select jsonb_agg(t.secenekler -> u.p order by u.o)
                       from unnest(k.perm) with ordinality u(p, o))
  from _parti_karistir k
 where t.question_id = k.id;

drop table if exists pg_temp._parti_karistir;
